using Microsoft.EntityFrameworkCore;

namespace Hub.Mapping;

public sealed class CanonicalHotelEntity
{
    /// <summary>Generated by the database; the public canonical id is derived from it.</summary>
    public long Id { get; set; }
}

public sealed class HotelIdentityEntity
{
    public long Id { get; set; }

    public string CanonicalId { get; set; } = string.Empty;

    public string Supplier { get; set; } = string.Empty;

    public string SupplierCode { get; set; } = string.Empty;
}

public sealed class HotelAliasEntity
{
    public string RetiredId { get; set; } = string.Empty;

    public string SurvivorId { get; set; } = string.Empty;
}

/// <summary>Provider-neutral model; the host chooses SQLite, PostgreSQL or another relational provider.</summary>
public sealed class MappingDbContext(DbContextOptions<MappingDbContext> options) : DbContext(options)
{
    public DbSet<CanonicalHotelEntity> CanonicalHotels => Set<CanonicalHotelEntity>();

    public DbSet<HotelIdentityEntity> Identities => Set<HotelIdentityEntity>();

    public DbSet<HotelAliasEntity> Aliases => Set<HotelAliasEntity>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<CanonicalHotelEntity>(entity =>
        {
            entity.ToTable("canonical_hotels");
            entity.HasKey(e => e.Id);
            entity.Property(e => e.Id).ValueGeneratedOnAdd();
        });

        modelBuilder.Entity<HotelIdentityEntity>(entity =>
        {
            entity.ToTable("hotel_identities");
            entity.HasKey(e => e.Id);
            entity.Property(e => e.Id).ValueGeneratedOnAdd();
            entity.Property(e => e.CanonicalId).HasMaxLength(32).IsRequired();
            entity.Property(e => e.Supplier).HasMaxLength(64).IsRequired();
            entity.Property(e => e.SupplierCode).HasMaxLength(128).IsRequired();
            entity.HasIndex(e => new { e.Supplier, e.SupplierCode }).IsUnique();
            entity.HasIndex(e => e.CanonicalId);
        });

        modelBuilder.Entity<HotelAliasEntity>(entity =>
        {
            entity.ToTable("hotel_aliases");
            entity.HasKey(e => e.RetiredId);
            entity.Property(e => e.RetiredId).HasMaxLength(32);
            entity.Property(e => e.SurvivorId).HasMaxLength(32).IsRequired();
            entity.HasIndex(e => e.SurvivorId);
        });
    }
}
